"""Measured floor plans for the reviewed 1672x941 cutaway compositions."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent/'assets/production/navigation/living-spaces.json'
DATA=json.loads(P.read_text()) if P.exists() else {}
def rect(v):
 x0,y0,x1,y1=v;return [[x0,y0],[x1,y0],[x1,y1],[x0,y1]]
def area(name,kinds,box,entry,holes=(),level=0,stairs=None):
 x0,y0,x1,y1=box;cx=(x0+x1)/2
 poly=[[x0+8,y0],[x1-8,y0],[x1,y0+8],[x1,y1-8],[x1-8,y1],[x0+8,y1],[x0,y1-8],[x0,y0+8]]
 candidates=[cx,x0+(x1-x0)*.32,x0+(x1-x0)*.68,x0+18,x1-18]
 cx=next((x for x in candidates if not any(h[0]-8<x<h[2]+8 and h[1]<y1 and h[3]>y1-22 for h in holes)),cx)
 path=stairs or ([[cx,y1+34],[cx,y1-10]] if not level else [list(entry),[cx,y1-10]])
 return dict(name=name,kinds=kinds.split('|'),polygon=poly,entries=[path],holes=[rect(h) for h in holes],level=level,foreground=[])
def stage(number,areas,blocks=None):
 key=f'S{number:02}'
 for i,a in enumerate(areas):a['id']=f'{key}-floor-{i+1:02}'
 if blocks is None:blocks=[(60,45,542,365),(625,40,990,365),(1070,40,1560,365),(60,425,542,719),(625,425,990,719),(1070,425,1560,719)]
 DATA[key]=dict(areas=areas,blockers=[rect(b) for b in blocks],measuredAgainst=f'quality/source/{key}-background.png')

